1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;
8	
9	/**
10	 * The duplicate block for a create-owner request. It rejects a create with a 409 only for an
11	 * <b>exact identity duplicate</b> — an existing owner with the same whole
12	 * {@link OwnerIdentityKey identity key} ({@code normalizedTelephone + '|' + email + '|' +
13	 * householdId}, keyed off the deterministic {@code householdId} resolved by
14	 * {@link DetermineOwnerHousehold} from {@code (lastName, postcode)}). This is always rejected,
15	 * even for a declared household member.
16	 *
17	 * <p>Merely sharing a household (same last name and postcode) with an existing owner is
18	 * <em>not</em> a hard duplicate: a genuine second member with a different telephone or email has a
19	 * distinct identity key and is allowed. Such a member is instead surfaced as a soft
20	 * {@code possibleDuplicate} by {@link FlagOwnerPossibleDuplicate} unless the request declares the
21	 * shared household with {@code sharesHousehold} true.
22	 */
23	public class CheckOwnerIdentityUnique {
24	
25	    public void service(@Val OwnerFieldsDto request, @Val HouseholdId householdId,
26	            OwnerRepository ownerRepository) throws DuplicateOwnerIdentityException {
27	        String identityKey = OwnerIdentityKey.of(request.getTelephone(), request.getEmail(),
28	                householdId.value());
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (existing.isDeleted()) {
31	                continue; // a soft-deleted owner never blocks a create
32	            }
33	            if (identityKey.equals(OwnerIdentityKey.forOwner(existing))) {
34	                throw new DuplicateOwnerIdentityException(identityKey);
35	            }
36	        }
37	    }
38	}
