1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import net.officefloor.plugin.variable.Out;
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	
12	/**
13	 * Resolves the deterministic shared {@code householdId} for a create-owner request. A "household"
14	 * is now keyed purely on {@code (lastName, postcode)}: the id is the first 12 hex characters of
15	 * {@code SHA-256(normalizedLastName + '|' + postcode)}, so any two owners with the same last name
16	 * and postcode independently derive an identical value and are, by definition, the same household.
17	 * The last name is normalized case-insensitively with runs of whitespace collapsed to a single
18	 * space and leading/trailing whitespace trimmed; the postcode is used as supplied (trimmed).
19	 *
20	 * <p>The id is computed for <em>every</em> request and published as {@link HouseholdId} for
21	 * {@link AssignOwnerHousehold} to stamp onto the new owner and for {@link CheckOwnerIdentityUnique}
22	 * to key duplicate detection on. Unlike before, this step neither inspects existing owners nor
23	 * stamps a link onto them — {@code sharesHousehold} no longer creates the link, it only lets a
24	 * second member of an existing household bypass the duplicate block (see
25	 * {@link CheckOwnerIdentityUnique}).
26	 */
27	public class DetermineOwnerHousehold {
28	
29	    public void service(@Val OwnerFieldsDto request, Out<HouseholdId> householdId) {
30	        String lastName = canonical(request.getLastName());
31	        String postcode = request.getPostcode() == null ? "" : request.getPostcode().trim();
32	        householdId.set(new HouseholdId(deriveHouseholdId(lastName, postcode)));
33	    }
34	
35	    /**
36	     * A stable household identifier: the first 12 hex characters of
37	     * {@code SHA-256(normalizedLastName + '|' + postcode)}, so every owner sharing the same last
38	     * name and postcode independently derives an identical value.
39	     */
40	    static String deriveHouseholdId(String normalizedLastName, String postcode) {
41	        String seed = normalizedLastName + "|" + postcode;
42	        try {
43	            byte[] digest = MessageDigest.getInstance("SHA-256")
44	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
45	            StringBuilder hex = new StringBuilder();
46	            for (int i = 0; i < 6; i++) {
47	                hex.append(String.format("%02X", digest[i]));
48	            }
49	            return hex.toString();
50	        }
51	        catch (NoSuchAlgorithmException ex) {
52	            throw new IllegalStateException("SHA-256 unavailable", ex);
53	        }
54	    }
55	
56	    private static String canonical(String value) {
57	        if (value == null) {
58	            return "";
59	        }
60	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
61	    }
62	}
