1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Stamps the soft-duplicate flags onto the newly built owner. A create that is not a hard
12	 * duplicate (already enforced by {@link CheckOwnerIdentityUnique}) is still flagged as a
13	 * possible duplicate when it shares an existing owner's last name (compared case-insensitively)
14	 * and postcode while carrying a different telephone. When such a match is found,
15	 * {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to the matching
16	 * owner's id (the earliest-created match when several exist); otherwise {@code possibleDuplicate}
17	 * is {@code false} and {@code possibleDuplicateOf} is left absent.
18	 *
19	 * <p>A declared household member (the request opted in with {@code sharesHousehold} true, so it
20	 * reached this step by bypassing the {@link CheckOwnerIdentityUnique duplicate block}) is never
21	 * flagged: a member the caller has explicitly declared is not a <em>suspected</em> duplicate.
22	 *
23	 * <p>Runs before {@link SaveOwner}, so the new owner is not yet persisted and cannot match itself.
24	 */
25	public class FlagOwnerPossibleDuplicate {
26	
27	    public void service(@Val Owner owner, @Val OwnerFieldsDto request,
28	            OwnerRepository ownerRepository) {
29	        owner.setPossibleDuplicate(false);
30	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            return; // a declared household member is not a suspected duplicate
32	        }
33	        String postcode = owner.getPostcode();
34	        if (postcode == null || postcode.isBlank()) {
35	            return; // no postcode to share — cannot be a possible duplicate
36	        }
37	        String lastName = canonical(owner.getLastName());
38	        String telephone = owner.getTelephone();
39	        Owner match = null;
40	        for (Owner existing : ownerRepository.findAll()) {
41	            if (postcode.equals(existing.getPostcode())
42	                    && lastName.equals(canonical(existing.getLastName()))
43	                    && !equalsTelephone(telephone, existing.getTelephone())) {
44	                if (match == null || existing.getId() < match.getId()) {
45	                    match = existing;
46	                }
47	            }
48	        }
49	        if (match != null) {
50	            owner.setPossibleDuplicate(true);
51	            owner.setPossibleDuplicateOf(match.getId());
52	        }
53	    }
54	
55	    private static boolean equalsTelephone(String a, String b) {
56	        return a == null ? b == null : a.equals(b);
57	    }
58	
59	    private static String canonical(String value) {
60	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
61	    }
62	}
