1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
9	
10	/**
11	 * Rejects an owner email whose domain is on the disposable-domain blocklist with a 400.
12	 * Runs after {@code NormalizeOwnerEmail}, so a present email is already syntactically
13	 * valid and lower-cased. An absent or blank email is left untouched (email is optional).
14	 */
15	public class ValidateOwnerEmailDomain {
16	
17	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
18	            "mailinator.com", "tempmail.com", "guerrillamail.com");
19	
20	    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
21	        String email = request.getEmail();
22	        if (email == null || email.trim().isEmpty()) {
23	            return;
24	        }
25	        int at = email.lastIndexOf('@');
26	        if (at < 0) {
27	            return; // syntax already enforced upstream; nothing to check here
28	        }
29	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
30	        if (BLOCKED_DOMAINS.contains(domain)) {
31	            throw new DisposableEmailDomainException(email);
32	        }
33	    }
34	}
