1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.mapper.LocalityLookup;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerPostcodeException;
9	
10	/**
11	 * Validates the owner's postcode WHEN PRESENT. An absent (null/blank) postcode is accepted,
12	 * keeping the request contract backward-compatible. When supplied it must be exactly 4 digits
13	 * and, if the city maps to a known region, fall within that region's inclusive range
14	 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
15	 * 4-digit postcode. Anything else is rejected with a 400 via
16	 * {@link InvalidOwnerPostcodeException}.
17	 */
18	public class ValidateOwnerPostcode {
19	
20	    /** Region -> inclusive 4-digit postcode range {low, high}. */
21	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
22	            "NSW", new int[] {2000, 2099},
23	            "VIC", new int[] {3000, 3099},
24	            "QLD", new int[] {4000, 4099});
25	
26	    public void service(@Val OwnerFieldsDto request) throws InvalidOwnerPostcodeException {
27	        String postcode = request.getPostcode();
28	        if (postcode == null || postcode.isBlank()) {
29	            return; // optional when absent
30	        }
31	        String city = request.getCity();
32	        if (!postcode.matches("[0-9]{4}")) {
33	            throw new InvalidOwnerPostcodeException(postcode, city);
34	        }
35	        int[] range = REGION_POSTCODES.get(LocalityLookup.regionFor(city));
36	        if (range == null) {
37	            return; // city with no known region accepts any 4-digit postcode
38	        }
39	        int value = Integer.parseInt(postcode);
40	        if (value < range[0] || value > range[1]) {
41	            throw new InvalidOwnerPostcodeException(postcode, city);
42	        }
43	    }
44	}
