3	/**
4	 * Thrown by {@code CheckOwnerIdentityUnique} when a create-owner request has the same whole
5	 * derived identity key (normalized telephone, email and household id) as an existing owner.
6	 * Consolidates the former separate telephone, email and household duplicate rejections into
7	 * one. Handled by {@link DuplicateOwnerIdentityExceptionHandler}, which responds 409.
8	 */
9	public class DuplicateOwnerIdentityException extends Exception {
10	
11	    public DuplicateOwnerIdentityException(String identityKey) {
12	        super("Identity is already used by another owner: " + identityKey);
13	    }
14	}
