4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.time.LocalDate;
15	import java.time.Period;
16	import java.util.Collection;
17	import java.util.List;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public abstract class OwnerMapper {
24	
25	    /**
26	     * Used to size the owner's household (the number of owners sharing the same
27	     * {@code householdId}) when scoring membership points. Field-injected so the
28	     * MapStruct-generated subclass, a Spring bean, receives it. May be {@code null} when the
29	     * mapper is used outside a Spring context; the household factor then scores nothing.
30	     */
31	    @Autowired
32	    protected OwnerRepository ownerRepository;
33	
34	    @Mapping(target = "selfLink", expression = "java(\"/api/owners/\" + owner.getId())")
35	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
36	    @Mapping(target = "displayName",
37	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
38	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
39	    @Mapping(target = "initials",
40	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
41	                    + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
42	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
43	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
44	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
45	    @Mapping(target = "locality", expression = "java(locality(owner))")
46	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
47	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
48	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
49	    @Mapping(target = "identityKey",
50	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey.forOwner(owner))")
51	    @Mapping(target = "telephoneDisplay",
52	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneNormalizer.toDisplay(owner.getTelephone()))")
53	    public abstract OwnerDto toOwnerDto(Owner owner);
54	
55	    public abstract Owner toOwner(OwnerDto ownerDto);
56	
57	    @Mapping(target = "id", ignore = true)
58	    @Mapping(target = "pets", ignore = true)
59	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
60	
61	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
62	
63	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
64	
65	    /**
66	     * Scores the owner's membership points. Starts at 0; add 2 when an email address is on
67	     * file; add 1 when the owner is the first with their name ({@code namesakeCount} is 0);
68	     * add 2 for a household of 3 or more members; add 3 once the owner's tenure spans at least
69	     * one full fiscal year (their registration fiscal year is before the current fiscal year).
70	     */
71	    protected Integer membershipPoints(Owner owner) {
72	        int points = 0;
73	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
74	            points += 2;
75	        }
76	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
77	            points += 1;
78	        }
79	        if (householdSize(owner) >= 3) {
80	            points += 2;
81	        }
82	        if (tenureFiscalYears(owner) >= 1) {
83	            points += 3;
84	        }
85	        return points;
86	    }
87	
88	    /**
89	     * The owner's numeric membership level: their {@link #naturalMembershipLevel(Owner) natural}
90	     * level, capped so it never exceeds one above the current maximum level among their existing
91	     * household members (other owners sharing the same {@code householdId}). With no existing
92	     * household member on file no cap applies, so the natural level is returned unchanged.
93	     */
94	    protected Integer membershipLevel(Owner owner) {
95	        int level = naturalMembershipLevel(owner);
96	        Integer householdMax = householdMaxMembershipLevel(owner);
97	        if (householdMax == null) {
98	            return level;
99	        }
100	        return Math.min(level, householdMax + 1);
101	    }
102	
103	    /**
104	     * Bands {@link #membershipPoints(Owner)} into the numeric membership level: 1 for 0-1
105	     * points, 2 for 2-3, 3 for 4-5, 4 for 6 or more. This is the owner's level before the
106	     * household ceiling in {@link #membershipLevel(Owner)} is applied.
107	     */
108	    private Integer naturalMembershipLevel(Owner owner) {
109	        int points = membershipPoints(owner);
110	        if (points <= 1) {
111	            return 1;
112	        }
113	        if (points <= 3) {
114	            return 2;
115	        }
116	        if (points <= 5) {
117	            return 3;
118	        }
119	        return 4;
120	    }
121	
122	    /**
123	     * The maximum {@link #naturalMembershipLevel(Owner) natural} membership level among the owner's
124	     * existing household members — the other, non-deleted owners sharing the same
125	     * {@code householdId}. Returns {@code null} when the owner has no household member on file (or
126	     * the repository is unavailable), signalling that no household cap applies.
127	     */
128	    private Integer householdMaxMembershipLevel(Owner owner) {
129	        String householdId = owner.getHouseholdId();
130	        if (householdId == null || ownerRepository == null) {
131	            return null;
132	        }
133	        Integer max = null;
134	        for (Owner existing : ownerRepository.findAll()) {
135	            if (existing.isDeleted() || !householdId.equals(existing.getHouseholdId())) {
136	                continue;
137	            }
138	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
139	                continue; // the owner is not their own household member
140	            }
141	            int level = naturalMembershipLevel(existing);
142	            if (max == null || level > max) {
143	                max = level;
144	            }
145	        }
146	        return max;
147	    }
148	
149	    /**
150	     * The number of owners sharing this owner's {@code householdId} (the persisted household
151	     * key derived from last name and postcode). Returns 1 when no household is on file or the
152	     * repository is unavailable, so the household factor scores nothing in those cases.
153	     */
154	    private long householdSize(Owner owner) {
155	        String householdId = owner.getHouseholdId();
156	        if (householdId == null || ownerRepository == null) {
157	            return 1;
158	        }
159	        long count = 0;
160	        for (Owner existing : ownerRepository.findAll()) {
161	            if (householdId.equals(existing.getHouseholdId())) {
162	                count++;
163	            }
164	        }
165	        return count;
166	    }
167	
168	    /**
169	     * The owner's tenure in whole elapsed fiscal years, measured from the fiscal year of their
170	     * {@code registrationDate} to the current fiscal year (fiscal years start on 1 July). Returns 0
171	     * when no registrationDate is on file (e.g. a brand-new owner before one is assigned), so such
172	     * an owner has zero tenure.
173	     */
174	    private int tenureFiscalYears(Owner owner) {
175	        LocalDate registrationDate = owner.getRegistrationDate();
176	        if (registrationDate == null) {
177	            return 0;
178	        }
179	        return org.springframework.samples.petclinic.rest.function.owner.FiscalYear
180	                .elapsed(registrationDate, LocalDate.now());
181	    }
182	
183	    /**
184	     * The owner's {@code fiscalYear} label {@code FY<YY>}, derived from the fiscal year of the
185	     * business-day-adjusted {@code registrationDate} (fiscal years start on 1 July). Returns
186	     * {@code null} when no registrationDate is on file, so the field is then absent from the
187	     * response.
188	     */
189	    protected String fiscalYear(Owner owner) {
190	        LocalDate registrationDate = owner.getRegistrationDate();
191	        if (registrationDate == null) {
192	            return null;
193	        }
194	        return org.springframework.samples.petclinic.rest.function.owner.FiscalYear.label(registrationDate);
195	    }
196	
197	    /**
198	     * Computes a single Luhn check digit (0-9) over the digits contained in the owner's
199	     * {@code customerCode}. Non-digit characters (separators) are ignored. Returns
200	     * {@code null} when no customer code has been assigned.
201	     */
202	    protected Integer checkDigit(Owner owner) {
203	        String code = owner.getCustomerCode();
204	        if (code == null) {
