24	     * @return the normalized address, or {@code ""} when {@code raw} is blank after normalization
25	     */
26	    static String normalize(String raw) {
27	        if (raw == null) {
28	            return "";
29	        }
30	        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
31	        if (collapsed.isEmpty()) {
32	            return "";
33	        }
34	        String[] tokens = collapsed.split(" ");
35	        StringBuilder result = new StringBuilder(collapsed.length());
36	        for (int i = 0; i < tokens.length; i++) {
37	            if (i > 0) {
38	                result.append(' ');
39	            }
40	            result.append(expand(tokens[i]));
41	        }
42	        return result.toString();
43	    }
44	
45	    private static String expand(String token) {
46	        switch (token) {
47	            case "ST":
48	                return "STREET";
49	            case "RD":
50	                return "ROAD";
51	            case "AVE":
52	                return "AVENUE";
53	            default:
