package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Stamps the soft-duplicate flags onto the newly built owner. A create that is not a hard
 * duplicate (already enforced by {@link CheckOwnerIdentityUnique}) is still flagged as a
 * possible duplicate when it shares an existing owner's last name (compared case-insensitively)
 * and postcode while carrying a different telephone. When such a match is found,
 * {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to the matching
 * owner's id (the earliest-created match when several exist); otherwise {@code possibleDuplicate}
 * is {@code false} and {@code possibleDuplicateOf} is left absent.
 *
 * <p>A declared household member (the request opted in with {@code sharesHousehold} true, so it
 * reached this step by bypassing the {@link CheckOwnerIdentityUnique duplicate block}) is never
 * flagged: a member the caller has explicitly declared is not a <em>suspected</em> duplicate.
 *
 * <p>Runs before {@link SaveOwner}, so the new owner is not yet persisted and cannot match itself.
 */
public class FlagOwnerPossibleDuplicate {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request,
            OwnerRepository ownerRepository) {
        owner.setPossibleDuplicate(false);
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // a declared household member is not a suspected duplicate
        }
        String postcode = owner.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return; // no postcode to share — cannot be a possible duplicate
        }
        String lastName = canonical(owner.getLastName());
        String telephone = owner.getTelephone();
        Owner match = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (postcode.equals(existing.getPostcode())
                    && lastName.equals(canonical(existing.getLastName()))
                    && !equalsTelephone(telephone, existing.getTelephone())) {
                if (match == null || existing.getId() < match.getId()) {
                    match = existing;
                }
            }
        }
        if (match != null) {
            owner.setPossibleDuplicate(true);
            owner.setPossibleDuplicateOf(match.getId());
        }
    }

    private static boolean equalsTelephone(String a, String b) {
        return a == null ? b == null : a.equals(b);
    }

    private static String canonical(String value) {
        return value == null ? "" : value.toLowerCase(Locale.ROOT);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Resolves the deterministic shared {@code householdId} for a create-owner request. A "household"
 * is now keyed purely on {@code (lastName, postcode)}: the id is the first 12 hex characters of
 * {@code SHA-256(normalizedLastName + '|' + postcode)}, so any two owners with the same last name
 * and postcode independently derive an identical value and are, by definition, the same household.
 * The last name is normalized case-insensitively with runs of whitespace collapsed to a single
 * space and leading/trailing whitespace trimmed; the postcode is used as supplied (trimmed).
 *
 * <p>The id is computed for <em>every</em> request and published as {@link HouseholdId} for
 * {@link AssignOwnerHousehold} to stamp onto the new owner and for {@link CheckOwnerIdentityUnique}
 * to key duplicate detection on. Unlike before, this step neither inspects existing owners nor
 * stamps a link onto them — {@code sharesHousehold} no longer creates the link, it only lets a
 * second member of an existing household bypass the duplicate block (see
 * {@link CheckOwnerIdentityUnique}).
 */
public class DetermineOwnerHousehold {

    public void service(@Val OwnerFieldsDto request, Out<HouseholdId> householdId) {
        String lastName = canonical(request.getLastName());
        String postcode = request.getPostcode() == null ? "" : request.getPostcode().trim();
        householdId.set(new HouseholdId(deriveHouseholdId(lastName, postcode)));
    }

    /**
     * A stable household identifier: the first 12 hex characters of
     * {@code SHA-256(normalizedLastName + '|' + postcode)}, so every owner sharing the same last
     * name and postcode independently derives an identical value.
     */
    static String deriveHouseholdId(String normalizedLastName, String postcode) {
        String seed = normalizedLastName + "|" + postcode;
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(seed.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder();
            for (int i = 0; i < 6; i++) {
                hex.append(String.format("%02X", digest[i]));
            }
            return hex.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 unavailable", ex);
        }
    }

    private static String canonical(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

